import flash.display.StageScaleMode;
import flash.display.StageAlign;
import flash.events.Event;

// 1. Hentikan timeline agar tidak auto-play
stop();

// 2. Atur alignment (perataan) ke pojok kiri atas
stage.align = StageAlign.TOP_LEFT;

// 3. Atur scale mode (mode skala)
// Ini kode yang membuat 1920x1080 pas di semua layar
stage.scaleMode = StageScaleMode.SHOW_ALL;


//event button kuis ke beranda
beranda_btn.addEventListener(MouseEvent.CLICK, changeKuisBeranda);
function changeKuisBeranda(e:MouseEvent):void{
	gotoAndStop(2);
}

//event button kuis ke materi
materi_btn.addEventListener(MouseEvent.CLICK, changeKuisMateri);
function changeKuisMateri(e:MouseEvent):void{
	gotoAndStop(3);
}

//event button kuis 1
btn_kuis1.addEventListener(MouseEvent.CLICK, changeKuis1);
function changeKuis1(e:MouseEvent):void{
	gotoAndStop(18);
}

